import jakarta.validation.constraints.Future;
import jakarta.validation.constraints.NotBlank;
import java.time.LocalDate;

enum TaskStatus { TODO, IN_PROGRESS, DONE }

enum TaskPriority { LOW, MEDIUM, HIGH }

// title không được để trống, dueDate phải là ngày trong tương lai.
record TaskRequest(
        @NotBlank(message = "title không được để trống") String title,
        String description,
        TaskStatus status,
        TaskPriority priority,
        @Future(message = "dueDate phải ở tương lai") LocalDate dueDate) {
}

import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/tasks")
class TaskController {

    private final TaskRepository repository;

    TaskController(TaskRepository repository) {
        this.repository = repository;
    }

    @GetMapping("/{id:[\\d]+}")
    ResponseEntity<Task> findById(@PathVariable long id) {
        return repository.findById(id)
                .map(ResponseEntity::ok)
                .orElseGet(() -> ResponseEntity.notFound().build());
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    Task create(@Valid @RequestBody TaskRequest request) {
        return repository.save(Task.from(request));
    }

    @PutMapping("/{id:[\\d]+}/status")
    Task updateStatus(@PathVariable long id,
            @Valid @RequestBody StatusUpdateRequest request) {
        return repository.updateStatus(id, request.status());
    }
}

import jakarta.validation.Constraint;
import jakarta.validation.ConstraintValidator;
import jakarta.validation.ConstraintValidatorContext;
import jakarta.validation.Payload;
import java.lang.annotation.*;
import java.util.Map;
import java.util.Set;

@Target(ElementType.TYPE)
@Retention(RetentionPolicy.RUNTIME)
@Constraint(validatedBy = StatusTransitionValidator.class)
@interface ValidStatusTransition {
    String message() default "chuyển trạng thái không hợp lệ";
    Class<?>[] groups() default {};
    Class<? extends Payload>[] payload() default {};
}

record StatusUpdateRequest(TaskStatus currentStatus, TaskStatus status) {
}

// @Target(TYPE): constraint xét cả hai field currentStatus và status
// của cùng một đối tượng, không thể xét từng field riêng lẻ.
@ValidStatusTransition
class StatusTransitionValidator
        implements ConstraintValidator<ValidStatusTransition, StatusUpdateRequest> {

    private static final Map<TaskStatus, Set<TaskStatus>> ALLOWED = Map.of(
            TaskStatus.TODO, Set.of(TaskStatus.IN_PROGRESS),
            TaskStatus.IN_PROGRESS, Set.of(TaskStatus.DONE, TaskStatus.TODO),
            TaskStatus.DONE, Set.of());

    @Override
    public boolean isValid(StatusUpdateRequest value, ConstraintValidatorContext context) {
        if (value == null || value.currentStatus() == null || value.status() == null) {
            return false;
        }
        return ALLOWED.getOrDefault(value.currentStatus(), Set.of()).contains(value.status());
    }
}

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
class TaskExceptionHandler {

    @ExceptionHandler(TaskNotFoundException.class)
    ProblemDetail handleNotFound(TaskNotFoundException ex) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    ProblemDetail handleValidation(MethodArgumentNotValidException ex) {
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(
                HttpStatus.BAD_REQUEST, "Dữ liệu Task không hợp lệ");
        problem.setTitle("Task validation failed");
        return problem;
    }
}

class TaskNotFoundException extends RuntimeException {
    TaskNotFoundException(long id) {
        super("Không tìm thấy Task với id=" + id);
    }
}
